import fs from 'node:fs';
const phase=process.argv[2]||'claim-cleanup',dir='outputs/practice-performance/'+phase,chunks=JSON.parse(fs.readFileSync(dir+'/bundle.json','utf8'));
const normalize=s=>s.split('/').pop().replace(/-[\w-]{8}\.js$/,'.js');
const baseline=JSON.parse(fs.readFileSync('outputs/practice-performance/baseline/chartlab-1.json','utf8'));
const requested=new Set(baseline.audits['network-requests'].details.items.filter(v=>v.resourceType==='Script').map(v=>normalize(new URL(v.url).pathname)));
const modules=(phase==='final'?chunks:chunks.filter(c=>requested.has(normalize(c.file)))).flatMap(c=>c.modules.map(m=>({...m,chunk:c.file}))).sort((a,b)=>b.renderedLength-a.renderedLength);
const clean=s=>s.replaceAll(process.cwd().replaceAll('\\','/')+'/','');
const reason=m=>phase==='final'?'Deferred/optional module; see exact immediate importers. This is not part of the 11.6 kB initial reading boot.':m.id.includes('/three/')?'The eager KnowledgeGraph branch imports Three; manual vendor grouping then puts it in every React route.':m.id.includes('/react-dom/')?'main.tsx imports createRoot; React is required for enhancement.':m.id.includes('chartLabRemainingCases')?'workbenchToolRoutes imports studyForSlug, which reaches all remaining study data.':m.id.includes('/data/chapters/')?'Workbench/learning-guide and diagram imports reach the shared chapter chunk.':m.id.includes('conceptsData')?'TradingToolsWorkbench imports glossary/reference tools eagerly.':m.id.includes('masterclass')?'TradingToolsWorkbench imports Masterclass views/data eagerly.':'See exact immediate importers below; the route-level Workbench and manual chunks share these modules.';
const top=modules.slice(0,15).map(m=>({module:clean(m.id),renderedBytes:m.renderedLength,chunk:m.chunk,importers:m.importers.map(clean),dynamicImporters:m.dynamicImporters.map(clean),reason:reason(m)}));
fs.writeFileSync(dir+(phase==='final'?'/largest-remaining-modules.json':'/largest-initial-modules.json'),JSON.stringify(top,null,2));
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const html=`<!doctype html><meta charset="utf-8"><title>Practice bundle map</title><style>body{font:15px system-ui;margin:32px;background:#fff;color:#18212b}h1{font-size:28px}.chunks{display:flex;flex-wrap:wrap;gap:8px}.chunk{border:1px solid #9baaba;padding:12px;flex:1 1 300px}.bar{background:#d9eafe;margin:4px 0;padding:7px;overflow-wrap:anywhere}summary{cursor:pointer}small{color:#41536b}li{margin:20px 0;overflow-wrap:anywhere}</style><h1>Practice bundle map — ${esc(phase)}</h1><p>Areas/widths use Rollup rendered module length before final chunk minification. Compressed per-chunk network sizes are in the Lighthouse evidence. This is not per-module compressed attribution.</p><div class="chunks">${chunks.filter(c=>c.bytes>10000).map(c=>`<section class="chunk"><h2>${esc(c.file)}</h2><small>${c.bytes.toLocaleString()} emitted bytes · imports ${c.imports.length}</small>${c.modules.sort((a,b)=>b.renderedLength-a.renderedLength).slice(0,12).map(m=>`<div class="bar" style="width:${Math.max(12,Math.min(96,m.renderedLength/c.modules.reduce((n,v)=>n+v.renderedLength,0)*100))}%">${esc(clean(m.id).split('/').slice(-3).join('/'))} · ${m.renderedLength.toLocaleString()}</div>`).join('')}</section>`).join('')}</div><h2>${phase==='final'?'15 largest remaining modules across deferred/optional chunks':'15 largest modules in baseline hub-requested chunks'}</h2><ol>${top.map(m=>`<li><strong>${esc(m.module)}</strong> — ${m.renderedBytes.toLocaleString()} bytes<p>${esc(m.reason)}</p><details><summary>Immediate importers</summary>${m.importers.map(esc).join('<br>')}</details></li>`).join('')}</ol>`;
fs.writeFileSync(dir+'/bundle-map.html',html);console.log(top.map(m=>`${m.renderedBytes}\t${m.module}`).join('\n'));
